    /\ munch [(bv_unsigned sp - 80, bv_unsigned sp); (TH + 2888, TH + 2904)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -48)
    /\ rw_cells bsegs m' (bv_unsigned sp + -48) [CB 16 j16; C8 s2; C8 s1; C8 s0; C8 ra]
